package oop.construtores.estudando.domain;public class Anime {    private String name;    private String type;    private String gender;    private String studio;    private int episodes;    public Anime(String name, String type, String gender, int episodes){        this();        this.name = name;        this.type = type;        this.gender = gender;        this.episodes = episodes;    }    public Anime(String name, String type, String gender,  String studio, int episodes){        this(name, type, gender, episodes);        this.studio = studio;    }    public Anime () {        System.out.println("Dentro do construtor sem argumentos");    }    public void imprimir () {        System.out.println(this.name);        System.out.println(this.type);        System.out.println(this.gender);        System.out.println(this.episodes);    }    public String getName () {        return this.name;    }    public String getType () {        return this.type;    }    public String getGender () {        return this.gender;    }    public int getEspisodes () {        return this.episodes;    }}